/* @layer shared-asset-extraction @kind logic */
import { hex } from '../c-hex';
import { NTILE, sheetRows } from '../shared/gato-bake';
import { dec } from '../shared/py-format';

interface Pose {
  label: string;
  rel: { rx: number; ry: number; tile: number }[];
  tiles: Uint8Array[];
  md5: string;
}

interface Face {
  name: string;
  facing: number;
  strikeAt: number;
  rear: number;
  strike: number;
}

const HEAD = [
  "// GENERATED by tools/gen/battle_gato_atkfaces.py -- do not edit. GATO's directional ATTACK poses\n",
  '// (disasm/notes/battle_animeng_corpus.md CAPTURE 1): the four-facing attack is a rear-up +\n',
  '// strike per facing, selected by $96DE (mvFacing[3]) exactly like the walk/idle facings. This\n',
  '// carries UP/LEFT/RIGHT; FRONT (facing 1) keeps the shipped kf8 rear-up + ctGatoSwipeKf GS\n',
  '// stream (front strike = tile-stream on a FIXED OAM). The SIDE strikes rearrange the OAM (the\n',
  '// claw cell 0x86 lunges: LEFT -34px, RIGHT +34px), so each carries its own strike assembly +\n',
  '// tiles. UP has no side-strike capture (no PC above GATO in this formation) -> its strike phase\n',
  "// holds the rear-up. Cells RELATIVE TO GATO'S LIVE FOOT ($1D12/$1D29); hf=vf=0 (corpus 1.1).\n",
  '// strikeAt = rel (rear-up onset) at which rear-up flips to strike (corpus 1.3). All poses\n',
  '// byte-verified vs the dossier assemblies. FIXTURE for the future anim-engine port (one rep\n',
  '// frame per phase; the within-pose tile stream is the C1/CC streamer boundary).\n',
  '#ifndef CT_BATTLE_GATO_ATKFACES_H\n#define CT_BATTLE_GATO_ATKFACES_H\n#include <stdint.h>\n\n',
  'typedef struct { int16_t relX, relY; uint16_t tile; } CtGatoAtkCell;\n',
  'typedef struct { const char* name; uint8_t facing; uint8_t strikeAt;\n',
  '                 uint16_t rearOff; uint8_t rearN; uint8_t rearTile;\n',
  '                 uint16_t strikeOff; uint8_t strikeN; uint8_t strikeTile; } CtGatoAtkFace;\n\n',
].join('');

/** The whole battle_gato_atkfaces.h. */
const atkFacesText = (poses: Pose[], faces: Face[]): string => {
  const out: string[] = [HEAD, 'static const CtGatoAtkCell ctGatoAtkCell[] = {\n'];
  const offs: [number, number][] = [];
  let off = 0;
  for (const p of poses) {
    out.push(`  // ${p.label} (md5 ${p.md5})\n`);
    for (const c of p.rel) out.push(`  { ${dec(c.rx, 4)}, ${dec(c.ry, 4)}, 0x${hex(c.tile, 3)} },\n`);
    offs.push([off, p.rel.length]);
    off += p.rel.length;
  }
  out.push('};\n\n');
  out.push(`#define CT_GATO_ATK_NFACE ${faces.length}\n`);
  out.push(`static const CtGatoAtkFace ctGatoAtkFace[CT_GATO_ATK_NFACE] = {\n`);
  for (const f of faces) {
    const [ro, rn] = offs[f.rear] as [number, number];
    const [so, sn] = offs[f.strike] as [number, number];
    out.push(`  { "${f.name}", ${f.facing}, ${f.strikeAt}, ${ro}, ${rn}, ${f.rear}, ${so}, ${sn}, ${f.strike} },\n`);
  }
  out.push('};\n\n');
  out.push(`#define CT_GATO_ATK_NTILE 0x${NTILE.toString(16).toUpperCase()}\n`);
  poses.forEach((p, k) => {
    out.push(`// ${p.label} tile sheet (capture VRAM OBJ half, body md5 ${p.md5})\n`);
    out.push(`static const uint8_t ctGatoAtkTiles${k}[CT_GATO_ATK_NTILE][32] = {\n`);
    out.push(sheetRows(p.tiles), '};\n');
  });
  const names = poses.map((_, k) => `ctGatoAtkTiles${k}`).join(', ');
  out.push(`static const uint8_t (*const ctGatoAtkTilesTab[${poses.length}])[32] = { ${names} };\n`, '#endif\n');
  return out.join('');
};

export type { Face, Pose };
export { atkFacesText };
